import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const XemHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [userRoom, setUserRoom] = useState('');
    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const [invoice, setInvoice] = useState(null); 
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const savedProfile = localStorage.getItem('userProfile');
        if (savedProfile) {
            const profile = JSON.parse(savedProfile);
            setUserRoom(profile.room_id || profile.room || '');
        }
    }, []);

    useEffect(() => {
        if (!userRoom) return;

        const fetchInvoiceByRoom = () => {
            setLoading(true);

            const allData = JSON.parse(localStorage.getItem('all_invoices') || '{}');
            const key = `${userRoom}_${selectedMonth}_${selectedYear}`;

            // Logic so sánh thời gian
            const isPast = selectedYear < currentYear || (selectedYear === currentYear && selectedMonth < currentMonth);
            const isFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth > currentMonth);

            if (allData[key]) {
                setInvoice(allData[key]);
            } else {
                setInvoice({
                    amount: 5000000,
                    content: '', 
                    // Phân loại trạng thái dựa trên thời gian
                    status: isPast ? 'paid' : (isFuture ? 'future' : 'unpaid'),
                    paidAt: isPast ? "Hệ thống xác nhận" : null
                });
            }
            setLoading(false);
        };

        fetchInvoiceByRoom();
    }, [userRoom, selectedMonth, selectedYear, currentMonth, currentYear]);

    const handlePayment = () => {
        if (!invoice.amount || invoice.amount <= 0) {
            alert("Số tiền không hợp lệ!");
            return;
        }

        const allData = JSON.parse(localStorage.getItem('all_invoices') || '{}');
        const key = `${userRoom}_${selectedMonth}_${selectedYear}`;

        const updatedInvoice = { 
            ...invoice, 
            status: 'paid', 
            paidAt: new Date().toLocaleString('vi-VN') 
        };

        allData[key] = updatedInvoice;
        localStorage.setItem('all_invoices', JSON.stringify(allData));
        setInvoice(updatedInvoice);

        alert(`Thanh toán thành công hóa đơn P.${userRoom}!`);
    };

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>💰 HÓA ĐƠN CƯ DÂN</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {[...Array(12)].map((_, i) => <option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => setSelectedYear(Number(e.target.value))} style={selectStyle}>
                        {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainFormStyle}>
                    {loading ? (
                        <div style={statusMsg}>Đang kiểm tra dữ liệu...</div>
                    ) : (
                        <div style={{ animation: 'fadeIn 0.4s' }}>
                            <div style={roomDisplay}>
                                <span style={{ fontSize: '14px', color: '#8b5e5e' }}>MÃ SỐ PHÒNG</span>
                                <div style={{ fontSize: '32px', fontWeight: '900', color: '#333' }}>{userRoom}</div>
                            </div>

                            {/* Form nhập liệu - Chỉ mở nếu là tháng hiện tại và chưa thanh toán */}
                            <div style={{ opacity: invoice?.status === 'future' ? 0.5 : 1 }}>
                                <div style={inputGroup}>
                                    <label style={labelStyle}>Số tiền (VNĐ):</label>
                                    <input 
                                        style={(invoice?.status === 'paid' || invoice?.status === 'future') ? inputDisabled : inputStyle} 
                                        type="number"
                                        value={invoice?.amount || ''}
                                        onChange={(e) => setInvoice({...invoice, amount: e.target.value})}
                                        disabled={invoice?.status !== 'unpaid'}
                                    />
                                </div>

                                <div style={inputGroup}>
                                    <label style={labelStyle}>Nội dung:</label>
                                    <textarea 
                                        style={(invoice?.status === 'paid' || invoice?.status === 'future') ? {...textareaStyle, ...inputDisabled} : textareaStyle} 
                                        value={invoice?.content || ''}
                                        onChange={(e) => setInvoice({...invoice, content: e.target.value})}
                                        disabled={invoice?.status !== 'unpaid'}
                                        placeholder="Tự nhập nội dung thanh toán..."
                                    />
                                </div>
                            </div>

                            {/* Hiển thị thông báo dựa trên trạng thái */}
                            {invoice?.status === 'paid' && (
                                <div style={successBox}>✅ ĐÃ THANH TOÁN</div>
                            )}

                            {invoice?.status === 'future' && (
                                <div style={futureBox}>⏳ CHƯA ĐẾN HẠN THANH TOÁN</div>
                            )}

                            {invoice?.status === 'unpaid' && (
                                <button onClick={handlePayment} style={btnPayStyle}>XÁC NHẬN THANH TOÁN</button>
                            )}
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

// --- STYLES ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)' };
const selectStyle = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const contentWrapperStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '20px' };
const mainFormStyle = { width: '100%', maxWidth: '450px', backgroundColor: '#fff', borderRadius: '30px', padding: '40px', boxShadow: '0 15px 35px rgba(0,0,0,0.2)' };
const roomDisplay = { textAlign: 'center', padding: '15px', background: '#fdf3f3', borderRadius: '20px', marginBottom: '25px', border: '2px dashed #8b5e5e' };
const inputGroup = { marginBottom: '20px' };
const labelStyle = { display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#666', fontSize: '13px' };
const inputStyle = { width: '100%', padding: '12px 15px', borderRadius: '12px', border: '1px solid #ddd', fontSize: '16px', outline: 'none', boxSizing: 'border-box' };
const inputDisabled = { backgroundColor: '#f5f5f5', color: '#999', cursor: 'not-allowed' };
const textareaStyle = { ...inputStyle, height: '80px', resize: 'none', fontFamily: 'inherit' };
const btnPayStyle = { width: '100%', padding: '16px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer' };
const successBox = { padding: '15px', borderRadius: '15px', backgroundColor: '#e6f4ea', color: '#1e7e34', textAlign: 'center', fontWeight: 'bold', border: '1px solid #c3e6cb' };
const futureBox = { padding: '15px', borderRadius: '15px', backgroundColor: '#fff4e5', color: '#664d03', textAlign: 'center', fontWeight: 'bold', border: '1px solid #ffe69c' };
const statusMsg = { textAlign: 'center', color: '#8b5e5e', fontWeight: '500' };

export default XemHoaDon;
